bash: cd my_website && cp package.json /tmp/pkg.bak && node -e '
const fs=require("fs");
const p=JSON.parse(fs.readFileSync("package.json","utf8"));
p.overrides={minimatch:"^11.0.1"};
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n");
' && npm install > /tmp/npm2.log 2>&1; echo "install exit=$?"; tail -4 /tmp/npm2.log; echo "=== audit:"; npm audit 2>&1 | tail -6

bash: cd my_website && cat > /tmp/t.njk <<'EOF'
A: {{ "now" | date: "%Y" }}
B: {{ "now" | date: "%Y" }}
EOF
node -e '
const n=require("nunjucks");
for (const s of [`{{ "now" | date: "%Y" }}`, `© {{ "now" | date: "%Y" }}`, `x {{ "now" | date("%Y") }}`]) {
  try { n.compileString(s); console.log("OK   ", s); }
  catch(e) { console.log("FAIL ", s, "->", e.message); }
}'

bash: cd my_website && node -e '
const n=require("nunjucks");
const env=new n.Environment();
const cases=[
 `{{ "now" | date: "%Y" }}`,
 `© {{ "now" | date: "%Y" }}`,
 `{{ "now" | date: "yyyy" }}`,
 `{{ "now" | date: "%Y" }} {{ site.name }}`,
];
for (const s of cases) {
  try { env.renderString(s,{site:{name:"X"}}); console.log("OK   ",JSON.stringify(s), "->", env.renderString(s,{site:{name:"X"}})); }
  catch(e) { console.log("FAIL ",JSON.stringify(s),"->",e.message.split("\n")[0]); }
}'

bash: cd my_website && node -e '
const n=require("nunjucks");
const env=new n.Environment();
env.addFilter("date", (v,f)=>String(f));
for (const s of [`{{ "now" | date: "%Y" }}`, `{{ "now" | date("%Y") }}`]) {
  try { console.log("OK   ",JSON.stringify(s),"->",env.renderString(s,{})); }
  catch(e){ console.log("FAIL ",JSON.stringify(s),"->",e.message.split("\n")[0]); }
}'

