bash: cd my_website && npx --yes js-yaml .github/workflows/deploy.yml > /tmp/wf.json 2>/tmp/yamlerr; echo "parse exit=$?"; cat /tmp/yamlerr | head -5
node -e '
const wf=require("/tmp/wf.json");
console.log("top-level permissions:", JSON.stringify(wf.permissions));
console.log("triggers:", Object.keys(wf.on||{}).join(","));
for (const [name,job] of Object.entries(wf.jobs)) {
  console.log(`job ${name}: perms=${JSON.stringify(job.permissions)}`);
  for (const s of job.steps) {
    const uses = s.uses || "";
    const pinned = !uses || /@[0-9a-f]{40}$/.test(uses);
    console.log(`   - ${s.name} :: ${uses||"run"} :: pinned=${pinned}`);
  }
}'

bash: cd my_website && node -e '
const fs=require("fs");
let s=fs.readFileSync("README.md","utf8");
if(!s.includes("PUSHING.md")){
  s=s.replace("One-time repository setup", "[`PUSHING.md`](PUSHING.md) has the exact `git` and `gh` commands for the first\npush and for running the workflow.\n\nOne-time repository setup");
  fs.writeFileSync("README.md",s);
}' && grep -n "PUSHING" README.md

